# Candidate: fill each zero from the nearest original nonzero seed on its NW-SE diagonal (constant c-r), preserving seeds.
out=[row[:] for row in grid]
for r in range(5):
    for c in range(5):
        if grid[r][c]==0:
            seeds=[(abs(rr-r),rr,cc,grid[rr][cc]) for rr in range(5) for cc in range(5)
                   if grid[rr][cc]!=0 and cc-rr==c-r]
            if seeds:
                _,rr,cc,color=min(seeds)
                out[r][c]=color
print('nearest-seed candidate:')
for row in out: print(*row)
